dency\ExportedNode\ExportedPhpDocNode":2:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1013:"/**
 * Reminds people of their planned follow-ups, and tells their manager about the ones left overdue — in-app and by
 * e-mail, once each.
 *
 * Run by the scheduler every five minutes for every company.
 *
 *  - **Reminder**: a follow-up is due for its reminder when it is planned to happen within the company's lead time
 *    (`followups.remind_minutes_before`, 30 minutes by default) — or is already late — and has not been reminded yet.
 *    Follow-ups more than a day late are left alone: after an outage, a flood of stale reminders helps nobody.
 *  - **Escalation**: a follow-up still planned `followups.escalate_after_hours` (24 by default; 0 = off) after it was
 *    due is reported to the manager of the team its person is on, once. Ones more than 30 days late are left alone.
 *
 * Each is *claimed* with a single conditional UPDATE before anything is sent, so two overlapping runs (or a retried one)
 * can never tell anybody twice; a follow-up that is rescheduled is re-armed for both.
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:23:"App\Modules\CRM\Console";s:4:"uses";a:16:{s:4:"user";s:15:"App\Models\User";s:14:"followupstatus";s:36:"App\Modules\CRM\Enums\FollowupStatus";s:8:"followup";s:31:"App\Modules\CRM\Models\Followup";s:4:"lead";s:27:"App\Modules\CRM\Models\Lead";s:9:"salesteam";s:32:"App\Modules\CRM\Models\SalesTeam";s:15:"salesteammember";s:38:"App\Modules\CRM\Models\SalesTeamMember";s:23:"followupduenotification";s:53:"App\Modules\CRM\Notifications\FollowupDueNotification";s:27:"followupoverduenotification";s:57:"App\Modules\CRM\Notifications\FollowupOverdueNotification";s:7:"tenancy";s:40:"App\Modules\Shared\Models\Scopes\Tenancy";s:9:"heartbeat";s:37:"App\Modules\Shared\Services\Heartbeat";s:15:"settingsservice";s:43:"App\Modules\Shared\Services\SettingsService";s:6:"format";s:33:"App\Modules\Shared\Support\Format";s:7:"slakind";s:35:"App\Modules\Workspace\Enums\SlaKind";s:11:"slapolicies";s:42:"App\Modules\Workspace\Services\SlaPolicies";s:7:"command";s:26:"Illuminate\Console\Command";s:6:"carbon";s:25:"Illuminate\Support\Carbon";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";s:26:"Illuminate\Console\Command";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:3:{i:0;O:54:"PHPStan\Dependency\ExportedNode\ExportedPropertiesNode":15:{s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPropertiesNode␀names";a:1:{i:0;s:9:"signature";}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedPropertiesNode␀phpDoc";N;s:60:"␀PHPStan\Depen