 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:22:"App\Modules\CRM\Models";s:4:"uses";a:25:{s:4:"user";s:15:"App\Models\User";s:11:"leadchannel";s:33:"App\Modules\CRM\Enums\LeadChannel";s:9:"leadstage";s:31:"App\Modules\CRM\Enums\LeadStage";s:8:"leadtype";s:30:"App\Modules\CRM\Enums\LeadType";s:10:"leadpolicy";s:35:"App\Modules\CRM\Policies\LeadPolicy";s:5:"block";s:32:"App\Modules\Masters\Models\Block";s:8:"district";s:35:"App\Modules\Masters\Models\District";s:6:"ledger";s:33:"App\Modules\Masters\Models\Ledger";s:5:"state";s:32:"App\Modules\Masters\Models\State";s:18:"approvabledocument";s:47:"App\Modules\Shared\Contracts\ApprovableDocument";s:12:"documenttype";s:37:"App\Modules\Shared\Enums\DocumentType";s:22:"approvalstateexception";s:52:"App\Modules\Shared\Exceptions\ApprovalStateException";s:10:"approvable";s:45:"App\Modules\Shared\Models\Concerns\Approvable";s:17:"belongstolocation";s:52:"App\Modules\Shared\Models\Concerns\BelongsToLocation";s:22:"validatesparentcompany";s:57:"App\Modules\Shared\Models\Concerns\ValidatesParentCompany";s:11:"tenantmodel";s:37:"App\Modules\Shared\Models\TenantModel";s:8:"fillable";s:48:"Illuminate\Database\Eloquent\Attributes\Fillable";s:9:"usepolicy";s:49:"Illuminate\Database\Eloquent\Attributes\UsePolicy";s:7:"builder";s:36:"Illuminate\Database\Eloquent\Builder";s:9:"belongsto";s:48:"Illuminate\Database\Eloquent\Relations\BelongsTo";s:7:"hasmany";s:46:"Illuminate\Database\Eloquent\Relations\HasMany";s:6:"hasone";s:45:"Illuminate\Database\Eloquent\Relations\HasOne";s:9:"morphmany";s:48:"Illuminate\Database\Eloquent\Relations\MorphMany";s:3:"arr";s:22:"Illuminate\Support\Arr";s:6:"carbon";s:25:"Illuminate\Support\Carbon";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀e