 * Creates teams and moves people on and off them. The single gate for team data; it does not decide who may (the
 * policies do) but it does keep the structure honest:
 *
 *  - a team's manager is an active user of the company, and unless the person saving can see everyone they can only
 *    run teams of which they are the manager;
 *  - a person is on **one team at a time**, and their memberships never overlap in time — the database backs this with
 *    a generated column, so two simultaneous requests cannot both add the same person;
 *  - leaving a team ends the membership (`left_on`, the last day, inclusive); nothing is deleted, so a past month's
 *    team can still be reconstructed.
 *
 * Input for saveTeam: ['team' => [code, name, manager_user_id, status, remarks]].
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:24:"App\Modules\CRM\Services";s:4:"uses";a:10:{s:4:"user";s:15:"App\Models\User";s:18:"fieldruleexception";s:45:"App\Modules\CRM\Exceptions\FieldRuleException";s:9:"salesteam";s:32:"App\Modules\CRM\Models\SalesTeam";s:15:"salesteammember";s:38:"App\Modules\CRM\Models\SalesTeamMember";s:13:"tenantcontext";s:40:"App\Modules\Shared\Tenancy\TenantContext";s:34:"uniqueconstraintviolationexception";s:54:"Illuminate\Database\UniqueConstraintViolationException";s:2:"db";s:29:"Illuminate\Support\Facades\DB";s:9:"validator";s:36:"Illuminate\Support\Facades\Validator";s:4:"rule";s:26:"Illuminate\Validation\Rule";s:19:"validationexception";s:41:"Illuminate\Validation\ValidationException";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:7:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;