 * Turns a target and the orders credited to people into "how far have we got" — exact decimal arithmetic, never floats.
 * What counts as achieved is the AchievementSource's business (see its contract for the policy: approved orders, net of
 * tax, cancellations out, returns in the period they are recorded).
 *
 * A **team** target adds up its members, but only for the days each was on the team: someone who joined mid-month brings
 * the orders from their joining day on, and someone who left takes none from the day after. The team history is kept
 * for this reason (members are never deleted).
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:24:"App\Modules\CRM\Services";s:4:"uses";a:4:{s:17:"achievementsource";s:43:"App\Modules\CRM\Contracts\AchievementSource";s:11:"salestarget";s:34:"App\Modules\CRM\Models\SalesTarget";s:15:"salesteammember";s:38:"App\Modules\CRM\Models\SalesTeamMember";s:14:"targetprogress";s:38:"App\Modules\CRM\Support\TargetProgress";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:2:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:6:"source";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:4